}

int __lxstat(int ver, const char *path, struct stat *buf) {
    (void)ver;
    return lstat(path, buf);
}

int __fxstatat(int ver, int dirfd, const char *path, struct stat *buf,
               int flags) {
    (void)ver;
    return fstatat(dirfd, path, buf, flags);
}

