                          unsigned int mask, struct statx *buf);

struct target {
    int valid;
    dev_t dev;
    ino_t ino;
};

static struct target g_target = {0, 0, 0};
static stat_fn_t g_real_stat;
static lstat_fn_t g_real_lstat;
static fstatat_fn_t g_real_fstatat;
static statx_fn_t g_real_statx;
